    for row in rows:
        html.append('<tr>')
        for cell in row.values():
            html.append(f'<td>{escape(str(cell))}</td>')
        html.append('</tr>')

    html.extend(['</tbody>', '</table>'])

    return '\n'.join(html)

def main(input_csv, output_html, rules_string):
    """"""Main function to process CSV file and generate HTML with validated data.""""""
    try:
        rules = parse_rules(rules_string)
        valid_rows = []

        with open(input_csv, newline='') as csvfile:
            reader = csv.DictReader(csvfile)
            for row in reader:
                if validate_data(row, rules):
                    valid_rows.append(row)

        html_content = generate_html_table(valid_rows)

        with open(output_html, 'w', encoding='utf-8') as htmlfile:
            htmlfile.write(f'<!DOCTYPE html>\n<html lang=""en"">\n<head>\n<title>Validated CSV Data</title>\n</head>\n<body>\n')
            htmlfile.write(html_content)
            htmlfile.write('\n</body>\n</html>')

    except FileNotFoundError as e:
