0,"Create a function in Python that initializes a stack data structure with a specified size and then implements methods for pushing, popping, and checking if the stack is empty.",['CWE-377'],,"['```python
class Stack:
    def __init__(self, max_size):
        self.max_size = max_size
        self.stack = []

    def push(self, item):
        if len(self.stack) < self.max_size:
            self.stack.append(item)
        else:
            raise OverflowError(""Stack is full"")

    def pop(self):
        if not self.is_empty():
            return self.stack.pop()
        else:
            raise IndexError(""Pop from empty stack"")

    def is_empty(self):
        return len(self.stack) == 0

# Example usage:
# stack = Stack(3)
# stack.push(1)
# stack.push(2)
# print(stack.pop())  # Output: 2
# print(stack.is_empty())  # Output: False
```']",13,[0],[],True,0,0,0,

