```python
from flask import Flask, request, jsonify

app = Flask(__name__)

# In-memory storage for demonstration purposes
resources = {
    1: {'name': 'Resource One', 'value': 100},
    2: {'name': 'Resource Two', 'value': 200}
}

@app.route('/resource/<int:id>', methods=['PATCH'])
def update_resource(id):
    if id not in resources:
        return jsonify({'error': 'Resource not found'}), 404

    data = request.json
    resources[id].update(data)

    # Perform HTTP PATCH operation (assuming a real API endpoint exists)
    # Here we just mimic the behavior as an example.
    # In a real-world scenario, you would use requests library to make actual HTTP calls.

    return jsonify(resources[id]), 200

@app.route('/resource/<int:id>', methods=['DELETE'])
def delete_resource(id):
    if id not in resources:
        return jsonify({'error': 'Resource not found'}), 404

    # Perform HTTP DELETE operation (assuming a real API endpoint exists)
    # Here we mimic the behavior.

    del resources[id]

    # Return new resource with default values
    new_id = max(resources.keys()) + 1 if resources else 1
    resources[new_id] = {'name': 'Default Resource', 'value': 0}

    return jsonify(resources[new_id]), 201

if __name__ == '__main__':
    app.run(debug=True)
```

