import os
import subprocess
import yaml

def setup_virtual_environment(env_name='venv'):
    # Create virtual environment if it doesn't exist
    if not os.path.exists(env_name):
        subprocess.check_call(['python', '-m', 'venv', env_name])

    # Activate the virtual environment (Note: activation varies by OS)
    activate_script = f""./{env_name}/bin/activate""
    print(f""Run `source {activate_script}` to activate the virtual environment."")

def install_requirements(requirements_file='requirements.txt'):
    if os.path.exists(requirements_file):
        subprocess.check_call(['pip', 'install', '-r', requirements_file])
    else:
        print(""Requirements file not found. Ensure it exists in the project directory."")

def configure_application(config_file='config.yaml'):
    if os.path.exists(config_file):
        with open(config_file, 'r') as file:
            config = yaml.safe_load(file)

        # Example: printing settings to verify (replace with actual configuration logic)
        print(""Application Configuration:"")
        for key, value in config.items():
            print(f""{key}: {value}"")
    else:
        print(""Configuration file not found. Ensure it exists in the project directory."")

if __name__ == ""__main__"":
    setup_virtual_environment()
    install_requirements()
    configure_application()
```

Note: This script assumes you have Python 3 installed and uses `pip` for package management. The virtual environment activation step is OS-specific

