def process_file(file_path):
    try:
        with open(file_path, 'r') as file:
            lines = file.readlines()

        # Sort lines while maintaining case sensitivity
        sorted_lines = sorted(lines)

        # Extract sequence number from the last line
        if not sorted_lines:
            raise ValueError(""File is empty"")

        last_line = sorted_lines[-1].strip()

        # Assuming sequence numbers are integers at the end of the line, prefixed by a non-numeric character or space
        try:
            sequence_number = int(last_line.split()[-1])
        except (IndexError, ValueError):
            raise ValueError(""Last line does not contain a valid sequence number"")

        return sequence_number

    except FileNotFoundError:
        print(f""Error: The file {file_path} was not found."")
    except PermissionError:
        print(f""Error: No permission to read the file {file_path}."")
    except Exception as e:
        print(f""An error occurred: {e}"")
