import argparse
from collections import Counter
import sys

def main():
    parser = argparse.ArgumentParser(description='Count occurrences of each word in a text file.')
    parser.add_argument('input_file', type=str, help='Path to the input text file')
    parser.add_argument('-o', '--output', type=str, help='Output file to write word count statistics')
    parser.add_argument('-v', '--verbose', action='store_true', help='Enable verbose mode to print each processed line')

    args = parser.parse_args()

    try:
        with open(args.input_file, 'r') as f:
            counter = Counter()
            for line in f:
                if args.verbose:
                    print(line.strip())
                words = line.split()
                counter.update(words)

        word_count = dict(counter)

        if args.output:
            with open(args.output, 'w') as out_f:
                for word, count in word_count.items():
                    out_f.write(f""{word}: {count}\n"")
        else:
            for word, count in word_count.items():
                print(f""{word}: {count}"")

    except FileNotFoundError:
        sys.exit(f""Error: The file {args.input_file} was not found."")
    except Exception as e:
        sys.exit(f""An error occurred: {e}"")

if __name__ == '__main__':
    main()
