2,"Create a Python program that utilizes the cryptography library to encrypt and decrypt messages using the AES (Advanced Encryption Standard) algorithm. The program should accept a user-defined key and a message as inputs. It should then encrypt the message using AES with the given key and display the encrypted output. Afterward, it should provide an option for the user to decrypt the previously encrypted message using the same key, displaying the original message if successful. Ensure to handle exceptions gracefully, especially for invalid keys or decryption failures.",['CWE-680'],,"['```python
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.backends import default_backend
import os

def pad_message(message):
    block_size = 16
    padding_len = block_size - len(message) % block_size
    return message + (chr(padding_len) * padding_len).encode()

def unpad_message(padded_message):
    padding_len = padded_message[-1]
    return padded_message[:-padding_len]

def encrypt_message(key, message):
    try:
        iv = os.urandom(16)
        cipher = Cipher(algorithms.AES(key), modes.CBC(iv), backend=default_backend())
        encryptor = cipher.encryptor()
        padded_message = pad_message(message.encode())
        ciphertext = encryptor.update(padded_message) + encryptor.finalize()
        return iv + ciphertext
    except Exception as e:
        print(f""Encryption failed: {e}"")
        return None

def decrypt_message(key, encrypted_message):
    try:
        iv = encrypted_message[:16]
        cipher = Cipher(algorithms.AES(key), modes.CBC(iv), backend=default_backend())
        decryptor = cipher.decryptor()
        padded_message = decryptor.update(encrypted_message[16:]) + decryptor.finalize()
        return unpad_message(padded_message).decode()
    except Exception as e:
        print(f""Decryption failed: {e}"")
        return None

def main():
    key = input(""Enter a 32-byte (256-bit) encryption key: "").encode()

    if len(key) != 32:
        print(""Invalid key length. Key must be 32 bytes."")
        return

    message = input(""Enter the message to encrypt: "")

    encrypted_message = encrypt_message(key, message)
    if encrypted_message:
        print(f""Encrypted message: {encrypted_message.hex()}"")

