import requests
import random
import json

def add_random_graph_elements(num_vertices, num_edges):
    # Generate random vertices and edges
    vertices = []
    edges = []

    for _ in range(num_vertices):
        vertex = {""id"": random.randint(1, 100), ""name"": f""Vertex{random.randint(1, 100)}""}
        vertices.append(vertex)

    for _ in range(num_edges):
        src_id = random.choice([v[""id""] for v in vertices])
        dest_id = random.choice([v[""id""] for v in vertices if v[""id""] != src_id])
        edge = {""source"": src_id, ""target"": dest_id}
        edges.append(edge)

    # Add properties to vertices and edges using standard library functions
    # (e.g., setting property values randomly or based on specific criteria)

    return vertices, edges

def graph_api_request(json_data):
    url = 'https://api.example.com/graph'
    headers = {'Content-Type': 'application/json'}

    try:
        response = requests.post(url=url,
                                 data=json.dumps(json_data),
                                 headers=headers)

        if response.status_code == 200:
            return response.json()

        else:
            print(f""Failed with status code {response.status_code}"")
            return None

    except Exception as e:
        print(f""An error occurred: {e}"")
        return None

