import random

class MersenneTwisterRandomGenerator:
    def __init__(self):
        self.generator = random.Random()

    def generate_random_integers(self, count, lower_bound=-1000, upper_bound=1000):
        return [self.generator.randint(lower_bound, upper_bound) for _ in range(count)]

def max_product_from_list(numbers):
    if not numbers:
        raise ValueError(""Input list cannot be empty."")

    max_product = float('-inf')
    min_product = float('inf')
    first_num = second_num = None

    for i in range(len(numbers)):
        num1 = numbers[i]

        # Find the maximum and minimum product possible
        if num1 * numbers[0] > max_product:
            max_product = num1 * numbers[0]
        if num1 * numbers[-1] < min_product:
            min_product = num1 * numbers[-1]

        for j in range(i + 1, len(numbers)):
            num2 = numbers[j]
            product = num1 * num2

            # Update the maximum and minimum products
            if product > max_product:
                max_product = product
            if product < min_product:
                min_product = product

    return max(max_product, min_product)

def max_random_product():
    mt_generator = MersenneTwisterRandomGenerator()

    # Generate a list of random integers
    numbers = mt_generator.generate_random_integers(10)
    print(f""Generated Numbers: {numbers}"")

    # Find the maximum product from these numbers
    return max_product_from_list(numbers)

# Example usage
result = max_random_product()
print(f""Maximum Product: {result}"")
```

