import argparse
from collections import defaultdict
import os

def parse_arguments():
    parser = argparse.ArgumentParser(description='Advanced Word count script')
    parser.add_argument('input_files', type=str, nargs='+', help='Input text files')
    parser.add_argument('-o', '--output_dir', type=str, required=True, help='Output directory for statistics files')
    parser.add_argument('-v', '--verbose_mode', action='store_true', help='Print each processed line details')

    return parser.parse_args()

def process_file(input_file, output_file, verbose):
    word_count = defaultdict(int)

    with open(input_file, 'r') as file:
        for line_num, line in enumerate(file, 1):
            if verbose:
                print(f""Processing line {line_num} in {input_file}: {line.strip()}"")

            words = line.strip().split()
            for word in words:
                word_count[word] += 1

    with open(output_file, 'w') as file:
        for word, count in sorted(word_count.items()):
            file.write(f""{word}: {count}\n"")

def process_files(input_files, output_dir, verbose):
    if not os.path.exists(output_dir):
        os.makedirs(output_dir)

    for input_file in input_files:
        base_name = os.path.basename(input_file)
        output_file = os.path.join(output_dir, f""{os.path.splitext(base_name)[0]}_word_count.txt"")

        process_file(input_file, output_file, verbose)

if __name__ == '__main__':
    args = parse_arguments()
    process_files(args.input_files, args.output_dir, args.verbose_mode)
