import os
from Crypto.Cipher import AES, PKCS1_OAEP
from Crypto.PublicKey import RSA
from Crypto.Random import get_random_bytes

# Define the RFCOMM Channel Connection Request structure
class RFCOMMRequest:
    def __init__(self, channel_id, source_address, destination_address):
        self.channel_id = channel_id
        self.source_address = source_address
        self.destination_address = destination_address

    def to_dict(self):
        return {
            'channel_id': self.channel_id,
            'source_address': self.source_address,
            'destination_address': self.destination_address
        }

# Define the Octree Node and Structure
class OctreeNode:
    def __init__(self, level=0, depth=3):
        self.children = [None] * 8
        self.data = []
        self.level = level
        self.depth = depth

    def insert(self, data):
        if self.level == self.depth:
            self.data.append(data)
            return

        index = self.get_index_from_data(data)
        if not self.children[index]:
            self.children[index] = OctreeNode(level=self.level + 1, depth=self.depth)

        self.children[index].insert(data)

    def get_largest_connection(self):
        largest = None
        for child in self.children:
            if child and (not largest or len(child.data) > len(largest.data)):
                largest = child

        return max((child.get_largest_connection() for child in self.children if child), default=self, key=lambda x: len(x.data))

    def get_index_from_data(self, data):
        # Simple hash function to determine index
        channel_id = int(data['channel_id'])
        return (channel_id >> (self.depth - self.level) * 3) & 7

class Octree:
    def __init__(self, depth=3):
        self.root = OctreeNode(depth=depth)

    def insert(self, data):
        self.root.insert(data)

    def get_largest_connection(self):
        return self.root.get_largest_connection().data

def encrypt_aes(data, key):
    cipher = AES.new(key, AES.MODE_EAX)
    ciphertext, tag = cipher.encrypt_and_digest(str(data).encode())
    return (cipher.nonce, tag, ciphertext)

def decrypt_aes(encrypted_data, key):
    nonce, tag, ciphertext = encrypted_data
    cipher = AES.new(key, AES.MODE_EAX, nonce=nonce)
    decrypted_data = cipher.decrypt_and_verify(ciphertext, tag)
    return eval(decrypted_data.decode())

def encrypt_rsa(data, public_key):
    cipher = PKCS1_OAEP.new(public_key)
    ciphertext = cipher.encrypt(str(data).encode())
    return ciphertext

def decrypt_rsa(encrypted_data, private_key):
    cipher = PKCS1_OAEP.new(private_key)
    decrypted_data = cipher.decrypt(encrypted_data)
    return eval(decrypted_data.decode())

def generateEncryptedRFCOMMRequests(numRequests, encryptionMethod):
    requests = []
    aes_key = get_random_bytes(16) if encryptionMethod == 'AES' else None
    rsa_key_pair = RSA.generate(2048) if encryptionMethod == 'RSA' else None

    for i in range(numRequests):
        channel_id = i
        source_address = f""00:0A:95:{os.urandom(2).hex()}""
        destination_address = f""00:0B:95:{os.urandom(2).hex()}""

        request = RFCOMMRequest(channel_id, source_address, destination_address)
        encrypted_request = {}

        if encryptionMethod == 'AES':
            encrypted_request['channel_id'] = encrypt_aes(request.channel_id, aes_key)
            encrypted_request['source_address'] = encrypt_aes(request.source_address, aes_key)
            encrypted_request['destination_address'] = encrypt_aes(request.destination_address, aes_key)

        elif encryptionMethod == 'RSA':
            encrypted_request['channel_id'] = encrypt_rsa(request.channel_id, rsa_key_pair.publickey())
            encrypted_request['source_address'] = encrypt_rsa(request.source_address, rsa_key_pair.publickey())
            encrypted_request['destination_address'] = encrypt_rsa(request.destination_address, rsa_key_pair.publickey())

        requests.append(encrypted_request)

    octree = Octree()

    for request in requests:
        octree.insert(request)

    largest_connection = octree.get_largest_connection()

    return {
        'requests': requests,
        'octree_initialized': True,
        'last_invocation_timestamp': None,  # Replace with actual timestamp if needed
        'largest_encrypted_request': largest_connection
    }

# Example usage:
result = generateEncryptedRFCOMMRequests(10, 'AES')
print(result['largest_encrypted_request'])
