struct RFCOMMRequest {
    source_address: String,
    destination_address: String,
    channel_id: u8,
}

impl RFCOMMRequest {
    fn new(channel_id: u8) -> Self {
        RFCOMMRequest {
            source_address: format!(""Source{}"", channel_id),
            destination_address: format!(""Dest{}"", channel_id),
            channel_id,
        }
    }

    fn encrypt_source(&mut self, method: &str) {
        match method {
            ""AES"" => self.source_address = format!(""AES-{}"", self.source_address),
            ""RSA"" => self.source_address = format!(""RSA-{}"", self.source_address),
            _ => (),
        }
    }

    fn encrypt_destination(&mut self, method: &str) {
        match method {
            ""AES"" => self.destination_address = format!(""AES-{}"", self.destination_address),
            ""RSA"" => self.destination_address = format!(""RSA-{}"", self.destination_address),
            _ => (),
        }
    }
}

