        if not validateAuthorization(transaction_id):
            return ""Error: Transaction is unauthorized.""

        payment_method = payment_data.get('payment_method')

        if payment_method == 'credit_card':
            card_number = payment_data.get('card_number')
            expiration_date = payment_data.get('expiration_date')
            cvv = payment_data.get('cvv')

            return processCreditCardPayment(card_number, expiration_date, cvv)

        elif payment_method == 'bank_transfer':
            account_number = payment_data.get('account_number')
            iban = payment_data.get('iban')

            return processBankTransfer(account_number, iban)

