class TreeNode:
    def __init__(self, value):
        self.value = value
        self.children = {}

def createCharacterMap(strings, root):
    char_map = {}

    for string in strings:
        node = root
        # Iterate over each character in the string to build or traverse the path
        for char in string:
            char_value = ord(char)  # Get ASCII value of the character

            # If this character is not already a child, create a new TreeNode
            if char_value not in node.children:
                node.children[char_value] = TreeNode(char_value)

            # Move to the next node (child)
            node = node.children[char_value]

        # Link string to the final node in its path
        if 'strings' not in node.__dict__:
            node.strings = []
        node.strings.append(string)

        char_map[string] = node

    return char_map

# Example usage
root_node = TreeNode(0)
string_array = [""hello"", ""world"", ""help""]
character_mapping = createCharacterMap(string_array, root_node)
```

