import re
from collections import defaultdict, Counter
from datetime import datetime

class LogParser:
    def __init__(self):
        self.log_pattern = re.compile(
            r'(?P<ip>\S+) - - \[(?P<timestamp>[^\]]+)\] ""(?P<method>\S+) (?P<url>\S+) HTTP/\d\.\d"" '
            r'(?P<status_code>\d{3}) (?P<response_time>\d+|-)'
        )
        self.daily_logs = defaultdict(lambda: defaultdict(list))
        self.url_response_times = defaultdict(list)
        self.ip_request_counts = Counter()

    def parse_log(self, log_line):
        match = self.log_pattern.match(log_line)
        if not match:
            raise ValueError(""Invalid log format"")

        data = match.groupdict()
        timestamp_str = data['timestamp']
        try:
            timestamp = datetime.strptime(timestamp_str, ""%d/%b/%Y:%H:%M:%S %z"")
        except ValueError as e:
            raise ValueError(f""Timestamp parsing error: {e}"")

        day_key = timestamp.date()
        hour_key = (day_key, timestamp.hour)
        url_endpoint = data['url']

        self.daily_logs[day_key][hour_key].append(data)
        if data['response_time'] != '-':
            self.url_response_times[url_endpoint].append(int(data['response_time']))
        self.ip_request_counts[(data['ip'], url_endpoint)] += 1

    def get_average_response_time(self, endpoint):
        times = self.url_response_times[endpoint]
        if not times:
            return None
        return sum(times) / len(times)

    def top_ip_addresses_for_endpoint(self, endpoint, timeframe=None):
        filtered_counts = {
            ip: count for (ip, ep), count in self.ip_request_counts.items()
            if ep == endpoint and (timeframe is None or self._is_within_timeframe(ip, timeframe))
        }
        return Counter(filtered_counts).most_common()

    def _is_within_timeframe(self, ip, timeframe):
        # Placeholder function to check if the IP falls within a specific timeframe
        # Implement based on actual requirements of how timeframes are defined and stored.
        return True

# Example usage:
