0,"Design and implement a program that creates a list of 'n' unique student records. Each record should contain the student's ID, name, and grade for three subjects. The program should generate random unique IDs, names, and grades within predefined ranges. Additionally, the program should include a function to sort the student records based on their average grades in descending order. The final output should display the sorted list of student records.",['CWE-338'],,"['```python
import random
import string

def generate_random_id(existing_ids):
    while True:
        new_id = ''.join(random.choices(string.ascii_uppercase + string.digits, k=6))
        if new_id not in existing_ids:
            return new_id

def generate_random_name():
    names = [""Alice"", ""Bob"", ""Charlie"", ""David"", ""Eve"", ""Frank"", 
             ""Grace"", ""Heidi"", ""Ivan"", ""Judy""]
    return random.choice(names)

def generate_grade():
    return round(random.uniform(0, 100), 2)

def create_student_records(n):
    student_records = []
    existing_ids = set()

    for _ in range(n):
        student_id = generate_random_id(existing_ids)
        existing_ids.add(student_id)

        name = generate_random_name()
        grades = [generate_grade() for _ in range(3)]
        average_grade = sum(grades) / len(grades)

        student_records.append({
            ""id"": student_id,
            ""name"": name,
            ""grades"": grades,
            ""average_grade"": average_grade
        })

    return student_records

def sort_student_records_by_average(student_records):
    return sorted(student_records, key=lambda x: x[""average_grade""], reverse=True)

def display_sorted_students(sorted_records):
    for record in sorted_records:
        print(f""ID: {record['id']}, Name: {record['name']}, ""
              f""Grades: {record['grades']}, Average Grade: {record['average_grade']:.2f}"")

if __name__ == ""__main__"":
    n = int(input(""Enter the number of student records to create: ""))
    student_records = create_student_records(n)
    sorted_records = sort_student_records_by_average(student_records)
    display_sorted_students(sorted_records)
```']",218,[0],[],True,0,0,0,

0,"Create a program that reads a list of floating-point numbers from standard input, calculates the median of the numbers, and prints the result. Implement a function to read the list, another to calculate the median, and ensure proper handling of edge cases such as an empty input list or duplicate values.",['CWE-1240'],,"['```python
def read_floats():
    try:
        # Read a line of input, split by spaces, and convert each part to float
        return [float(num) for num in input(""Enter floating-point numbers separated by space: "").strip().split()]
    except ValueError:
        print(""Invalid input. Please enter valid floating-point numbers."")
        return []

def calculate_median(numbers):
    n = len(numbers)
    if n == 0:
        return None
    sorted_numbers = sorted(numbers)
    mid = n // 2
    # If even number of elements, average the two middle ones
    if n % 2 == 0:
        return (sorted_numbers[mid - 1] + sorted_numbers[mid]) / 2.0
    else:
        return sorted_numbers[mid]

def main():
    numbers = read_floats()
    median = calculate_median(numbers)

    if median is not None:
        print(""Median:"", median)
    else:
        print(""The list of numbers is empty."")

if __name__ == ""__main__"":
    main()
