import requests

def fetch_product_details(product_ids):
    base_url = ""http://your-django-backend/api/products/""
    product_data = {}

    try:
        for pid in product_ids:
            response = requests.get(f""{base_url}{pid}/"")

            if response.status_code == 200:
                product_data[pid] = response.json()
            else:
                product_data[pid] = {""error"": f""Product with ID {pid} not found.""}

    except Exception as e:
        return {""error"": ""An error occurred while fetching product details."", ""exception"": str(e)}

    return product_data
