from Crypto.Cipher import AES
import sys

def read_integers_and_print_largest(count, key):
    try:
        # Check for positive count
        if count <= 0:
            raise ValueError(""Count must be a positive integer."")

        # Allocate memory dynamically (in Python using list)
        arr = [None] * count

        print(f""Please enter {count} integers:"")

        # Read and store integers, ensuring valid input
        for i in range(count):
            while True:
                try:
                    value = int(input(f""Integer {i + 1}: ""))
                    arr[i] = value
                    break
                except ValueError:
                    print(""Invalid integer. Please enter a valid integer."")

        # Find the largest element using recursion
        largest = print_largest_helper(arr, 0, count - 1)

        # Encrypt and print the largest element
        encrypted_largest = encrypt(largest, key)
        print(f""The largest number is: {encrypted_largest}"")

    except Exception as e:
        print(f""An error occurred: {e}"")
        sys.exit(1)


def print_largest_helper(arr, start, end):
    if start == end:
        return arr[start]

    mid = (start + end) // 2
    left_largest = print_largest_helper(arr, start, mid)
    right_largest = print_largest_helper(arr, mid + 1, end)

    return max(left_largest, right_largest)


def encrypt(data, key):
    # Ensure data is a multiple of block size (16 bytes for AES-128)
    data_bytes = str(data).encode('utf-8')
    padded_data = pad(data_bytes)

    cipher = AES.new(key.encode('utf-8'), AES.MODE_ECB)  # Using ECB mode
    encrypted_data = cipher.encrypt(padded_data)

    return encrypted_data.hex()  # Return as hex for readability


def pad(data):
    block_size = 16
    padding_length = block_size - len(data) % block_size
    padding = chr(padding_length) * padding_length
    return data + padding.encode('utf-8')


if __name__ == ""__main__"":
    try:
        count = int(input(""Enter the number of integers: ""))
        key = ""16charsecret""  # AES requires a 16, 24, or 32-byte key

        if len(key) not in [16, 24, 32]:
            raise ValueError(""Key must be either 16, 24, or 32 bytes long."")

        read_integers_and_print_largest(count, key)

    except ValueError as e:
        print(f""Invalid input: {e}"")
        sys.exit(1)
