import json
import random
from enum import Enum

class JsonFactoryRegistry:
    def __init__(self):
        self.registry = {}

    def add_factory(self, id, factory_func):
        self.registry[id] = factory_func

    def create_instance(self, id, **kwargs):
        if id not in self.registry:
            raise ValueError(f""No factory function registered for ID {id}"")
        return self.registry[id](**kwargs)

class JsonObject:
    def __init__(self, data):
        self.data = data

    def to_json(self):
        return json.dumps(self.data)

class CustomObject(JsonObject):
    pass

def create_custom_object(data):
    return CustomObject(data)

def create_random_custom_object(data_length=100, name_length=20):
    random_data = {
        'name': ''.join(random.choices('abcdefghijklmnopqrstuvwxyz', k=name_length)),
        'age': random.randint(18, 99),
        'additional_info': {
            ''.join(random.choices('abcdefghijklmnopqrstuvwxyz', k=random.randint(1, 5))): ''.join(random.choices('abcdefghijklmnopqrstuvwxyz', k=random.randint(5, 20)))
            for _ in range(random.randint(1, 5))
        }
    }
    return CustomObject(random_data)

def validate_custom_object(obj):
    if not isinstance(obj.data.get('name'), str) or not isinstance(obj.data.get('age'), int) or not isinstance(obj.data.get('additional_info'), dict):
        raise ValueError(""Invalid Custom Object"")

def generate_custom_objects(num_objects=3):
    objects_list = []
    for _ in range(num_objects):
        name_length = random.randint(10, 30)
        data = {
            ""name"": ''.join(random.choices('abcdefghijklmnopqrstuvwxyz', k=name_length)),
            ""age"": random.randint(18, 99),
            ""additional_info"": {
                ''.join(random.choices('abcdefghijklmnopqrstuvwxyz', k=random.randint(1, 5))): ''.join(random.choices('abcdefghijklmnopqrstuvwxyz', k=random.randint(5, 20)))
                for _ in range(random.randint(1, 5))
            }
        }

        obj = CustomObject(data)

        validate_custom_object(obj)

        objects_list.append((obj.data['name'], obj.to_json()))

    return objects_list

json_factory_registry = JsonFactoryRegistry()
json_factory_registry.add_factory(""custom"", create_custom_object)
json_factory_registry.add_factory(""random_custom"", create_random_custom_object)

# Example usage:
