def modify_filename_extension(filename, digits, new_file_type):
    dot_index = filename.rfind('.')

    if dot_index == -1:
        return filename

    extension = filename[dot_index:]

    current_digits = len(extension)

    if current_digits > digits:
        trimmed_extension = ' ' * (digits - 1) + extension[-(digits - 1):]
    elif current_digits < digits:
        trimmed_extension = extension.ljust(digits, ' ')
    else:
        trimmed_extension = extension

    return f""{filename[:dot_index]}{trimmed_extension}{new_file_type}""
