            ""packetsSent"": nfdata.packetsSent,
            ""timestamp"": nfdata.timestamp // 1000
        }
        return json.dumps(stats)

def generate_nfstats():
    """"""Generates an array of NFDataPlaneStats_t structures.""""""
    stats_array = []

    for _ in range(10):
        current_timestamp = int(time.time() * 1e9)

        nfdata = NFDataPlaneStats_t()
        nfdata.timestamp = current_timestamp

        stats_array.append(nfdata)

    return stats_array

# Example usage:
if __name__ == ""__main__"":
    parser = NFDataParser()

    # Generate statistics
    nfstats = generate_nfstats()

    # Convert each structure to JSON
    for stat in nfstats:
        json_string = parser.nfdata_to_json(stat)
        print(json_string)
