class HashTable:
    def __init__(self, capacity):
        self.capacity = capacity
        self.size = 0
        self.table = [None] * capacity

    def _hash(self, key):
        return hash(key) % self.capacity

    def add_item(self, unique_id, data):
        if self.search(unique_id) is not None:
            raise ValueError(f""Item with ID {unique_id} already exists."")

        index = self._hash(unique_id)
        while self.table[index] is not None:
            if self.table[index][0] == unique_id:
                raise ValueError(f""Duplicate item ID detected: {unique_id}"")
            index = (index + 1) % self.capacity

        self.table[index] = (unique_id, data)
        self.size += 1

    def search(self, unique_id):
        index = self._hash(unique_id)
        start_index = index
        while self.table[index] is not None:
            if self.table[index][0] == unique_id:
                return self.table[index][1]
            index = (index + 1) % self.capacity
            if index == start_index: 
                break

        raise KeyError(f""Item with ID {unique_id} does not exist."")

    def remove_item(self, unique_id):
        index = self._hash(unique_id)
        start_index = index
        while self.table[index] is not None:
            if self.table[index][0] == unique_id:
                self.table[index] = None
                self.size -= 1

                # Rehash the subsequent items in the cluster to fill gaps
                next_index = (index + 1) % self.capacity
                while self.table[next_index] is not None:
                    rehashed_item = self.table[next_index]
                    self.table[next_index] = None
                    self.size -= 1
                    self.add_item(rehashed_item[0], rehashed_item[1])
                    next_index = (next_index + 1) % self.capacity
                return

            index = (index + 1) % self.capacity
            if index == start_index:
                break

        raise KeyError(f""Item with ID {unique_id} does not exist."")

    def display_items(self):
        for item in self.table:
            if item is not None:
                print(item)

# Example usage
hash_table = HashTable(10)
hash_table.add_item(""item1"", ""data1"")
hash_table.add_item(""item2"", ""data2"")

print(""Searching for 'item1':"", hash_table.search(""item1""))

hash_table.display_items()

hash_table.remove_item(""item1"")
print(""\nAfter removing 'item1':"")
hash_table.display_items()
```

