from datetime import datetime

class TicketManager:
    def __init__(self):
        self.tickets = {}

    def add_ticket(self, ticket_id, attendee_name, expiration_date):
        if not isinstance(ticket_id, str) or not isinstance(attendee_name, str) or not isinstance(expiration_date, datetime):
            raise ValueError(""Invalid input types"")

        if ticket_id in self.tickets:
            raise ValueError(""Ticket ID already exists"")

        if expiration_date <= datetime.now():
            raise ValueError(""Expiration date must be in the future"")

        self.tickets[ticket_id] = {
            'attendee_name': attendee_name,
            'expiration_date': expiration_date,
            'status': 'active'
        }

    def update_ticket(self, ticket_id, **kwargs):
        if ticket_id not in self.tickets:
            raise ValueError(""Ticket ID does not exist"")

        ticket = self.tickets[ticket_id]

        attendee_name = kwargs.get('attendee_name')
        expiration_date = kwargs.get('expiration_date')
        status = kwargs.get('status')

        if attendee_name is not None and not isinstance(attendee_name, str):
            raise ValueError(""Invalid attendee name"")

        if expiration_date is not None:
            if not isinstance(expiration_date, datetime) or expiration_date <= datetime.now():
                raise ValueError(""Invalid expiration date"")
            ticket['expiration_date'] = expiration_date

        if status is not None and status not in ['active', 'inactive']:
            raise ValueError(""Invalid status"")

        if attendee_name is not None:
            ticket['attendee_name'] = attendee_name

        if status is not None:
            ticket['status'] = status

    def delete_ticket(self, ticket_id):
        if ticket_id not in self.tickets:
            raise ValueError(""Ticket ID does not exist"")

        del self.tickets[ticket_id]

    def verify_ticket_validity(self, ticket_id):
        if ticket_id not in self.tickets:
            return False

        ticket = self.tickets[ticket_id]
        current_time = datetime.now()

        return (
            ticket['status'] == 'active' and 
            ticket['expiration_date'] > current_time
        )

    def query_attendee_info(self, attendee_name):
        result = [
            (ticket_id, details) for ticket_id, details in self.tickets.items()
            if details['attendee_name'] == attendee_name
        ]

        return result
