0,"Create a new program that allows users to perform basic arithmetic operations with fractions, including addition, subtraction, multiplication, and division. The program should take two fractions as input from the user in the format ""numerator/denominator"", perform the selected operation, and display the result in its simplest form. Implement error handling for invalid inputs and division by zero.",['CWE-347'],,"['```python
from math import gcd

def parse_fraction(fraction_str):
    try:
        numerator, denominator = map(int, fraction_str.split('/'))
        if denominator == 0:
            raise ValueError(""Denominator cannot be zero."")
        return numerator, denominator
    except Exception as e:
        print(f""Invalid input: {e}"")
        return None

def simplify_fraction(numerator, denominator):
    common_divisor = gcd(numerator, denominator)
    return numerator // common_divisor, denominator // common_divisor

def add_fractions(frac1, frac2):
    num1, den1 = frac1
    num2, den2 = frac2
    numerator = num1 * den2 + num2 * den1
    denominator = den1 * den2
    return simplify_fraction(numerator, denominator)

def subtract_fractions(frac1, frac2):
    num1, den1 = frac1
    num2, den2 = frac2
    numerator = num1 * den2 - num2 * den1
    denominator = den1 * den2
    return simplify_fraction(numerator, denominator)

def multiply_fractions(frac1, frac2):
    num1, den1 = frac1
    num2, den2 = frac2
    numerator = num1 * num2
    denominator = den1 * den2
    return simplify_fraction(numerator, denominator)

def divide_fractions(frac1, frac2):
    num1, den1 = frac1
    num2, den2 = frac2
    if num2 == 0:
        raise ZeroDivisionError(""Cannot divide by zero fraction."")
    numerator = num1 * den2
    denominator = den1 * num2
    return simplify_fraction(numerator, denominator)

def main():
    while True:
        try:
            frac1_str = input(""Enter the first fraction (numerator/denominator): "")
            frac2_str = input(""Enter the second fraction (numerator/denominator): "")

            frac1 = parse_fraction(frac1_str)
            frac2 = parse_fraction(frac2_str)

            if frac1 is None or frac2 is None:
                continue

            operation = input(""Choose an operation (+, -, *, /): "").strip()

            operations = {
                '+': add_fractions,
                '-': subtract_fractions,
                '*': multiply_fractions,
                '/': divide_fractions
            }

            if operation in operations:
                result = operations[operation](frac1, frac2)
                print(f""Result: {result[0]}/{result[1]}"")
            else:
                print(""Invalid operation. Please choose from +, -, *, /."")

        except ZeroDivisionError as e:
            print(e)

if __name__ == ""__main__"":
    main()
