import json
from datetime import datetime

class NFDataPlaneStats:
    _registry = {}

    def __init__(self, id, data):
        self.id = id
        self.data = data

    @classmethod
    def register_factory(cls, id, factory_func):
        cls._registry[id] = factory_func

    @classmethod
    def create_instance(cls, id, *args, **kwargs):
        if id in cls._registry:
            return cls._registry[id](*args, **kwargs)
        raise ValueError(f""No factory registered for ID: {id}"")

    def to_json(self):
        return json.dumps({
            'id': self.id,
            'data': self.data
