import logging
from datetime import datetime

# Configure logging
logging.basicConfig(filename='csv_header.log', level=logging.INFO,
                    format='%(asctime)s - %(levelname)s - %(message)s')

def constructCSVHeader(*args):
    try:
        if not args:
            return """"

        # Validate input types
        for arg in args:
            if not isinstance(arg, str):
                raise TypeError(f""Invalid type encountered: {type(arg).__name__}. Expected a string."")

        header = ','.join(args)
        logging.info(""CSV Header Created Successfully"", extra={'headers': list(map(type, args))})
        return header

    except Exception as e:
        logging.error(f""Error creating CSV Header: {str(e)}"")
        raise

# Example usage
if __name__ == ""__main__"":
    try:
        print(constructCSVHeader(""Name"", ""Age"", ""Occupation""))
        # This will log successfully created headers and their types
    except Exception as e:
        print(f""An error occurred: {e}"")
