            'RX_UE_INFORMATION_TAG': random.random(),
            'CRCFLAG': random.choice([0, 1])
        }

    def addRandomPropertiesToVertices(self, rnti_value):
        self.vertices[rnti_value]['properties'].update(
            self.generate_random_properties()
        )

    def addRandomPropertiesToEdges(self, edge):
        edge.update(self.generate_random_properties())

    def generate_random_properties(self):
        return {
            'prop1': random.random(),
            'prop2': f""val{random.randint(1000, 9999)}""
        }

