import time

def min_non_adjacent_product(nums):
    if len(nums) < 3:
        return None  # Not enough elements to have non-adjacent pairs

    max1 = max2 = float('-inf')
    for num in nums:
        if num > max1:
            max2, max1 = max1, num
        elif num > max2:
            max2 = num

    min1 = min2 = float('inf')
    for num in nums:
        if num < min1:
            min2, min1 = min1, num
        elif num < min2:
            min2 = num

    # Calculate non-adjacent products and track time taken per multiplication
    min_product = float('inf')
    duration_list = []

    for i in range(len(nums)):
        for j in range(i + 2, len(nums)):
            start_time = time.time_ns()
            product = nums[i] * nums[j]
            end_time = time.time_ns()

            duration_microseconds = (end_time - start_time) / 1000
            print(f""Duration for multiplication: {duration_microseconds} microseconds"")
            duration_list.append(duration_microseconds)

            if product < min_product:
                min_product = product

    return min_product, duration_list

# Example usage
