import random
from datetime import datetime
import uuid

class EventLogEntry:
    def __init__(self, log_id, category, message, metadata):
        self.log_id = log_id
        self.category = category
        self.message = message
        self.metadata = metadata

def generate_event_log_entries(N, sort_by='log_id', order='asc'):
    if N <= 0:
        raise ValueError(""Number of entries must be greater than zero."")

    categories = [""INFO"", ""WARNING"", ""ERROR""]
    templates = {
        ""INFO"": ""Information: Operation completed successfully."",
        ""WARNING"": ""Warning: Potential issue detected."",
        ""ERROR"": ""Error: An unexpected error occurred.""
    }

    entries = []

    for _ in range(N):
        log_id = f""{datetime.now().isoformat()}-{uuid.uuid4().hex}""
        category = random.choice(categories)
        message = templates[category]
        metadata = {}

        entry = EventLogEntry(log_id, category, message, metadata)

        try:
            entries.append(entry)
        except MemoryError as e:
            raise RuntimeError(""Memory allocation failed."") from e

    if sort_by not in ['log_id', 'timestamp']:
        raise ValueError(""sort_by must be either 'log_id' or 'timestamp'."")

    reverse = (order == 'desc')

    try:
        entries.sort(key=lambda x: getattr(x, sort_by), reverse=reverse)
    except Exception as e:
        raise RuntimeError(f""Sorting failed: {str(e)}"")

    return entries

# Example usage
try:
    logs = generate_event_log_entries(10, sort_by='timestamp', order='asc')
    for log in logs:
        print(vars(log))
except Exception as error:
    print(f""An error occurred: {error}"")
```

