import asyncio
import aioredis
import logging
import json
import os
from contextlib import asynccontextmanager

# Configure logging for errors
logging.basicConfig(filename='redis_errors.log', level=logging.ERROR)

class RedisPool:
    def __init__(self, servers, max_connections=10, timeout=5):
        self.servers = servers
        self.max_connections = max_connections
        self.timeout = timeout
        self.pools = {}

    async def initialize_pools(self):
        for server in self.servers:
            try:
                pool = await aioredis.create_pool(
                    server,
                    maxsize=self.max_connections,
                    timeout=self.timeout
                )
                self.pools[server] = pool
                logging.info(f""Successfully connected to {server}"")
            except Exception as e:
                logging.error(f""Failed to connect to {server}: {e}"")

    async def acquire(self, server):
        try:
            if server not in self.pools:
                await self.initialize_pools()
            return await self.pools[server].acquire()
        except Exception as e:
            logging.error(f""Error acquiring connection from {server}: {e}"")
            for fallback_server in self.servers:
                if fallback_server != server:
                    try:
                        pool = await aioredis.create_pool(
                            fallback_server,
                            maxsize=self.max_connections,
                            timeout=self.timeout
                        )
                        self.pools[fallback_server] = pool
                        return await pool.acquire()
                    except Exception as ex:
                        logging.error(f""Failover to {fallback_server} failed: {ex}"")
            raise

    async def release(self, conn):
        try:
            server = [s for s in self.servers if conn._pool.address == s][0]
            await self.pools[server].release(conn)
        except Exception as e:
            logging.error(f""Error releasing connection from {conn._pool.address}: {e}"")

    def update_servers(self, servers):
        self.servers = servers
        asyncio.run(self.initialize_pools())

@asynccontextmanager
async def AsyncRedisManager(pool, server):
    conn = await pool.acquire(server)
    try:
        yield conn
    finally:
        await pool.release(conn)

def load_config(config_path=None):
    if config_path and os.path.exists(config_path):
        with open(config_path, 'r') as file:
            return json.load(file)
    else:
        servers = os.environ.get('REDIS_SERVERS', 'redis://localhost').split(',')
        max_connections = int(os.environ.get('MAX_CONNECTIONS', 10))
        timeout = int(os.environ.get('TIMEOUT', 5))
        return {'servers': servers, 'max_connections': max_connections, 'timeout': timeout}

async def main():
    config = load_config()
    redis_pool = RedisPool(config['servers'], config['max_connections'], config['timeout'])
    await redis_pool.initialize_pools()

    async with AsyncRedisManager(redis_pool, 'redis://localhost') as conn:
        # Example usage
        await conn.set('key', 'value')
        value = await conn.get('key')
        print(value)

if __name__ == '__main__':
    asyncio.run(main())
```

This code implements a Python program that connects to multiple Redis servers using `aioredis`, with custom connection pooling, failover support, error logging, and dynamic configuration updates. The `RedisPool` class manages connections, while the `AsyncRedisManager` context manager ensures proper closure of connections. Configuration can be updated dynamically from JSON files or environment variables.']",0,[0],[],True,0,0,0,

