2,"Create a new programming task that involves developing a custom data structure for managing a collection of employee records in an organization. The task should include implementing functions for adding, removing, and updating employee records, as well as searching for employees by various criteria such as name or department. The program should also handle input validation and error checking to ensure that the data entered is correct and within acceptable ranges. Additionally, implement a feature that allows exporting the employee records to a CSV file and importing them from a CSV file, adhering to standard CSV formatting rules.",['CWE-680'],,"['```python
import csv

class Employee:
    def __init__(self, id, name, department):
        self.id = id
        self.name = name
        self.department = department

class EmployeeManager:
    def __init__(self):
        self.employees = {}

    def add_employee(self, emp_id, name, department):
        if not isinstance(emp_id, int) or emp_id <= 0:
            raise ValueError(""Invalid employee ID"")
        if not isinstance(name, str) or not name.strip():
            raise ValueError(""Invalid employee name"")
        if not isinstance(department, str) or not department.strip():
            raise ValueError(""Invalid department"")

        if emp_id in self.employees:
            raise KeyError(f""Employee with ID {emp_id} already exists"")

        self.employees[emp_id] = Employee(emp_id, name, department)

    def remove_employee(self, emp_id):
        if emp_id not in self.employees:
            raise KeyError(f""No employee found with ID {emp_id}"")

        del self.employees[emp_id]

    def update_employee(self, emp_id, name=None, department=None):
        if emp_id not in self.employees:
            raise KeyError(f""No employee found with ID {emp_id}"")

        if name is not None:
            if not isinstance(name, str) or not name.strip():
                raise ValueError(""Invalid employee name"")
            self.employees[emp_id].name = name

        if department is not None:
            if not isinstance(department, str) or not department.strip():
                raise ValueError(""Invalid department"")
            self.employees[emp_id].department = department

    def search_by_name(self, name):
        return [emp for emp in self.employees.values() if name.lower() in emp.name.lower()]

    def search_by_department(self, department):
        return [emp for emp in self.employees.values() if department.lower() == emp.department.lower()]

    def export_to_csv(self, file_path):
        with open(file_path, mode='w', newline='') as file:
            writer = csv.writer(file)
            writer.writerow(['ID', 'Name', 'Department'])
            for emp in self.employees.values():
                writer.writerow([emp.id, emp.name, emp.department])

    def import_from_csv(self, file_path):
        with open(file_path, mode='r') as file:
            reader = csv.DictReader(file)
            for row in reader:
                try:
                    emp_id = int(row['ID'])
                    name = row['Name']
                    department = row['Department']
                    self.add_employee(emp_id, name, department)
                except ValueError as e:
                    print(f""Skipping invalid record: {row}. Error: {e}"")
                except KeyError as e:
                    print(f""Skipping duplicate record: {row}. Error: {e}"")

# Example usage
manager = EmployeeManager()
manager.add_employee(1, ""John Doe"", ""HR"")
manager.update_employee(1, department=""Human Resources"")
print(manager.search_by_name(""John""))
manager.export_to_csv('employees.csv')
manager.import_from_csv('employees.csv')
```']",282,[0],[],True,0,0,0,

0,"Design a function that constructs an array of Network Device Configuration Request (NDCR) PDU structures based on the specifications provided in Prompt 3. The function should also integrate the optimizations mentioned in Prompt 4. The solution should incorporate dynamic memory allocation, efficient memory management techniques, validation checks, error handling procedures, logging functionalities, and the implementation of randomization elements.",['CWE-680'],,"['```python
import random
import logging

class NDCRPDU:
    def __init__(self, config_id):
        self.config_id = config_id

    def to_bytes(self):
        # Simulate converting the PDU structure to bytes for transmission
        return str(self.config_id).encode()

def construct_ndcr_pdus(num_devices):
    try:
        if num_devices <= 0:
            raise ValueError(""Number of devices must be greater than zero."")

        logging.info(f""Starting construction of {num_devices} NDCR PDUs."")

        pdus = []
        for i in range(num_devices):
            config_id = random.randint(1000, 9999)  # Randomization element
            pdu = NDCRPDU(config_id)
            pdus.append(pdu)

        logging.info(f""Successfully constructed {num_devices} NDCR PDUs."")

        return pdus

    except MemoryError:
        logging.error(""Memory allocation failed. Unable to construct all requested NDCR PDUs."")
        # Implement additional memory management or cleanup if necessary
        raise

    except Exception as e:
        logging.error(f""An error occurred: {e}"")
        raise

def optimize_pdus(pdus):
    try:
        optimized_pdus = [pdu for pdu in pdus if pdu.config_id % 2 == 0]  # Example optimization: Keep even config_ids
        logging.info(""Optimization applied to PDUs."")

        return optimized_pdus

    except Exception as e:
        logging.error(f""An error occurred during optimization: {e}"")
        raise

# Configure logging
logging.basicConfig(level=logging.INFO)

# Usage example
num_devices = 10
try:
    pdus = construct_ndcr_pdus(num_devices)
    optimized_pdus = optimize_pdus(pdus)
except Exception as e:
    print(f""Failed to process PDUs: {e}"")
