import random
import string

class AIRCOMMAND_MSG:
    def __init__(self, msg_id, mac_address, payload):
        self.msg_id = msg_id
        self.mac_address = mac_address
        self.payload = payload

def generate_random_mac():
    return ':'.join(['{:02x}'.format(random.randint(0, 255)) for _ in range(6)])

def generate_random_payload(size=10):
    return ''.join(random.choices(string.ascii_letters + string.digits, k=size))

def generate_aircommand_msgs(num_msgs):
    msgs = []
    for i in range(num_msgs):
        msg_id = f""ID_{i+1}""
        mac_address = generate_random_mac()
        payload = generate_random_payload()
        msgs.append(AIRCOMMAND_MSG(msg_id, mac_address, payload))
    return msgs

# Example usage
aircommand_msgs = generate_aircommand_msgs(5)
for msg in aircommand_msgs:
    print(f""ID: {msg.msg_id}, MAC: {msg.mac_address}, Payload: {msg.payload}"")
