import sys
import os
from concurrent.futures import ThreadPoolExecutor
import argparse

def parse_arguments():
    parser = argparse.ArgumentParser(description='Process a CSV-like file with custom delimiter.')
    parser.add_argument('file_path', type=str, help='Path to the input file')
    parser.add_argument('--delimiter', type=str, default=',', help='Delimiter for splitting lines')
    parser.add_argument('--ignore-empty-lines', action='store_true', help='Ignore empty lines in processing')
    return parser.parse_args()

def read_file(file_path):
    try:
        with open(file_path, 'r') as file:
            return file.readlines()
    except FileNotFoundError:
        print(f""Error: The file '{file_path}' was not found."")
        sys.exit(1)
    except IOError as e:
        print(f""IO Error: {e}"")
        sys.exit(1)

def split_line(line, delimiter):
    return line.strip().split(delimiter)

def is_empty_line(line, ignore_empty_lines):
    if ignore_empty_lines:
        return not line.strip()
    return False

def calculate_average(numbers):
    if not numbers:
        return float('nan')
    return sum(float(num) for num in numbers) / len(numbers)

def process_line(index, line, delimiter, ignore_empty_lines):
    if is_empty_line(line, ignore_empty_lines):
        return None
    columns = split_line(line, delimiter)
    numeric_data = [col for col in columns if col.replace('.', '', 1).isdigit()]
    average = calculate_average(numeric_data)
    return f""Line {index + 1}: {line.strip()} | Average: {average}""

def main():
    args = parse_arguments()
    lines = read_file(args.file_path)

    if not lines:
        print(""Error: The file is empty."")
        sys.exit(1)

    results = []
    with ThreadPoolExecutor() as executor:
        futures = [
            executor.submit(process_line, i, line, args.delimiter, args.ignore_empty_lines)
            for i, line in enumerate(lines)
        ]
        for future in futures:
            result = future.result()
            if result:
                results.append(result)

    for result in results:
        print(result)

if __name__ == ""__main__"":
    main()
