import hashlib
import requests
import json

def compute_sha256(file_path):
    chunk_size = 4096
    hash_object = hashlib.sha256()
    with open(file_path, 'rb') as file:
        while True:
            chunk = file.read(chunk_size)
            if not chunk:
                break
            hash_object.update(chunk)
    return hash_object.hexdigest()

def authenticate_oauth_and_get_user_info(client_id, client_secret):
    url = 'https://oauth-provider.com/token'
    fields = {
        'grant_type': 'client_credentials',
        'client_id': client_id,
        'client_secret': client_secret,
    }

    response = requests.post(url, data=fields)

    if response.status_code == 200:
        response_data = json.loads(response.text)

        if 'access_token' in response_data:
            access_token = response_data['access_token']

            def make_api_request(url, headers=None):
                headers = headers or {'Authorization': f'Bearer {access_token}'}
                response = requests.get(url, headers=headers)
                return response.json()

            user_info_url = 'https://api.example.com/user'
            user_info = make_api_request(user_info_url)

            print(""User Information:"", user_info)

        else:
            print(""Failed to retrieve access token."")
    else:
        print(""Authentication failed. Status code:"", response.status_code)

