def generate_sensor_data_entries(n):
    sensor_ids = [f""sensor_{i}"" for i in range(1, 101)]
    measurement_types = [""temperature"", ""humidity"", ""pressure""]

    def get_random_value(measurement_type):
        if measurement_type == ""temperature"":
            return round(random.uniform(-50.0, 50.0), 2)
        elif measurement_type == ""humidity"":
            return random.randint(0, 100)
        elif measurement_type == ""pressure"":
            return random.randint(900, 1100)

    entries = []
    for _ in range(n):
        entry = {
            ""sensor_id"": random.choice(sensor_ids),
            ""measurement_type"": random.choice(measurement_types),
            ""value"": get_random_value(random.choice(measurement_types))
        }
        entries.append(entry)

    return entries
