import socket
import sys

def domain_to_ip(domain):
    try:
        ip_address = socket.gethostbyname(domain)
        return bytearray(ip_address.split('.'), 'utf-8')
    except socket.gaierror as e:
        print(f""Error: {e}"")
        return bytearray([2])  # Error code for failed resolution
    except Exception as e:
        print(f""Unexpected error: {e}"")
        return bytearray([1])  # General error code

def main():
    if len(sys.argv) != 2:
        print(""Usage: script.py <domain>"")
        sys.exit(0)

    domain = sys.argv[1]
    result = domain_to_ip(domain)

    if result == bytearray([2]):
        print(f""Resolution failed for domain '{domain}'."")
    elif result == bytearray([1]):
        print(""An unexpected error occurred."")
    else:
        print(f""The IP address of {domain} is: {'.'.join(map(str, result))}"")

if __name__ == ""__main__"":
    main()
```

