```python
from flask import Flask, request, jsonify
import jwt
import hashlib
from functools import wraps

app = Flask(__name__)
SECRET_KEY = 'your_secret_key'
users_db = {
    ""user1"": {""password_hash"": hashlib.sha256(b""mypassword"").hexdigest(), ""roles"": [""user""]},
    # Add more users as needed
}
roles_permissions = {
    ""admin"": [""read"", ""write"", ""delete""],
    ""user"": [""read""]
}

def hash_password(password):
    return hashlib.sha256(password.encode()).hexdigest()

def token_required(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('Authorization')
        if not token:
            return jsonify({'message': 'Token is missing!'}), 403
        try:
            data = jwt.decode(token, SECRET_KEY, algorithms=[""HS256""])
            current_user = users_db.get(data['username'])
            if not current_user:
                raise Exception(""User not found."")
        except Exception as e:
            return jsonify({'message': str(e)}), 401
        return f(current_user, *args, **kwargs)
    return decorated

def role_required(role):
    def decorator(f):
        @wraps(f)
        def decorated_function(current_user, *args, **kwargs):
            if role not in current_user[""roles""]:
                return jsonify({'message': 'Permission denied!'}), 403
            return f(current_user, *args, **kwargs)
        return decorated_function
    return decorator

class RoleManager:
    @staticmethod
    def add_role(username, role):
        if username in users_db:
            users_db[username][""roles""].append(role)

    @staticmethod
    def remove_role(username, role):
        if username in users_db and role in users_db[username][""roles""]:
            users_db[username][""roles""].remove(role)

    @staticmethod
    def get_permissions(username):
        permissions = set()
        for role in users_db.get(username, {}).get(""roles"", []):
            permissions.update(roles_permissions.get(role, []))
        return list(permissions)

@app.route('/login', methods=['POST'])
def login():
    auth = request.json
    user = users_db.get(auth['username'])
    if not user or hash_password(auth['password']) != user['password_hash']:
        return jsonify({'message': 'Login failed!'}), 401

    token = jwt.encode({
        'username': auth['username']
    }, SECRET_KEY, algorithm=""HS256"")

    return jsonify({'token': token})

@app.route('/secure-data', methods=['GET'])
@token_required
@role_required('user')
def secure_data(current_user):
    permissions = RoleManager.get_permissions(current_user[""username""])
    return jsonify({'data': 'This is secure data.', 'permissions': permissions})

if __name__ == '__main__':
    app.run(debug=True)
```

This code sets up a simple Flask application with JWT authentication and role-based access control. Users can log in to receive a token, which they must provide to access protected routes. The `RoleManager` class manages user roles and permissions dynamically.']",0,[0],[],True,0,0,0,

