import os
import random
from Crypto.PublicKey import RSA

def generate_rsa_keys(n):
    primes = []
    for _ in range(n):
        prime = generate_large_prime()
        primes.append(prime)

    p, q = random.sample(primes, 2)
    n_value = p * q
    phi_n = (p-1) * (q-1)

    e = find_coprime(phi_n)
    d = mod_inverse(e, phi_n)

    return RSA.construct((n_value, e, d))

def encrypt_message(message, public_key):
    return [pow(ord(char), public_key.e, public_key.n) for char in message]

def decrypt_message(ciphertext, private_key):
    return ''.join([chr(pow(char, private_key.d, private_key.n)) for char in ciphertext])

def generate_large_prime():
    while True:
        prime_candidate = random.getrandbits(1024) | 7
        if is_prime(prime_candidate):
            return prime_candidate

def is_prime(number):
    if number < 2:
        return False
    if number == 2:
        return True
    if number % 2 == 0:
        return False

    for i in range(3, int(number ** 0.5) + 1, 2):
        if number % i == 0:
            return False

    return True

def find_coprime(phi_n):
    while True:
        e = random.randint(2, phi_n-1)
        if gcd(e, phi_n) == 1:
            return e

def gcd(a, b):
    while b != 0:
        a, b = b, a % b
    return a

def mod_inverse(a, m):
    m0, x0, x1 = m, 0, 1
    if m == 1:
        return 0

    while a > 1:
        q = a // m
        m, a = a % m, m
        x0, x1 = x1 - q * x0, x0

    if x1 < 0:
        x1 += m0

    return x1

# Example usage and testing the system with dynamic data set handling.
keys = generate_rsa_keys(4)
public_key = keys.publickey()
private_key = keys

message = ""Hello, RSA!""
ciphertext = encrypt_message(message, public_key)
decrypted_message = decrypt_message(ciphertext, private_key)

print(f""Original Message: {message}"")
print(f""Encrypted Message: {ciphertext}"")
print(f""Decrypted Message: {decrypted_message}"")
