import unittest
from timeit import default_timer as timer

class UnionFind:
    def __init__(self, size):
        self.parent = list(range(size))

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        rootX = self.find(x)
        rootY = self.find(y)
        if rootX != rootY:
            self.parent[rootY] = rootX

class SandeshClient:
    # Placeholder class for simulating server interactions
    pass

def findDisjointPairs(array):
    size = len(array)
    uf = UnionFind(size)

    for i in range(1, size):
        uf.union(i - 1, array[i])

    disjoint_pairs_count = 0

    for i in range(size):
        for j in range(i + 1, size):
            if uf.find(i) != uf.find(j):
                disjoint_pairs_count += 1

    return disjoint_pairs_count

class TestDisjointPairs(unittest.TestCase):
    def setUp(self):
        self.client = SandeshClient()

    def test_empty_array(self):
        result = findDisjointPairs([])
        expected = 0
        self.assertEqual(result, expected)

    def test_single_element_array(self):
        array = [1]
        result = findDisjointPairs(array)
        expected = 0
        self.assertEqual(result, expected)

    def test_two_disjoint_elements(self):
        array = [1, 2]
        result = findDisjointPairs(array)
        expected = 1
        self.assertEqual(result, expected)

    def test_multiple_disjoint_pairs(self):
        array = [1, 3, 5, 7, 9]  # All elements are disjoint
        result = findDisjointPairs(array)
        expected = 10  # Total pairs: (1,2), (1,3) ... , (8,9)
        self.assertEqual(result, expected)

    def test_performance(self):
        start_time = timer()
        large_array = list(range(1000))
        _ = findDisjointPairs(large_array)
        end_time = timer()
        print(f""Execution time for 1000 elements: {end_time - start_time} seconds"")

if __name__ == '__main__':
    unittest.main(argv=[''], exit=False)
